using System.Runtime.InteropServices;

class EnvVarCheck
{
    // On .NET 9+/Linux, Environment.GetEnvironmentVariable returns null for
    // empty values. Use /proc/self/environ to detect if the var is defined.
    static bool IsEnvironmentVariableDefined(string name)
    {
        if (!RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
            return Environment.GetEnvironmentVariable(name) != null;

        try
        {
            var raw = File.ReadAllBytes("/proc/self/environ");
            var entries = System.Text.Encoding.UTF8.GetString(raw)
                .Split('\0', StringSplitOptions.RemoveEmptyEntries);
            var prefix = name + "=";
            foreach (var entry in entries)
            {
                if (entry.StartsWith(prefix, StringComparison.Ordinal) ||
                    entry == name)
                    return true;
            }
        }
        catch { }

        return false;
    }

